CREATE OR REPLACE FUNCTION public.notify_staff_new_reservation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault', 'pg_temp'
AS $function$
declare
  v_key text;
begin
  begin
    select decrypted_secret into v_key
    from vault.decrypted_secrets
    where name = 'tonda_service_role_key';

    if v_key is null then
      raise warning 'notify_staff_new_reservation: tonda_service_role_key missing from vault; alert skipped';
      return NEW;
    end if;

    perform net.http_post(
      url := 'https://qeepslmexektwqhxzwqs.supabase.co/functions/v1/notify-staff-reservation',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_key
      ),
      body := jsonb_build_object('record', row_to_json(NEW)),
      timeout_milliseconds := 10000
    );
  exception when others then
    raise warning 'notify_staff_new_reservation: http_post failed: %', sqlerrm;
  end;

  return NEW;
end;
$function$
;

CREATE TRIGGER on_reservation_approved AFTER UPDATE OF status ON public.reservations FOR EACH ROW WHEN (((old.status = 'pending'::text) AND (new.status = 'confirmed'::text))) EXECUTE FUNCTION notify_reservation_approved();

CREATE TRIGGER on_reservation_completed AFTER UPDATE ON public.reservations FOR EACH ROW EXECUTE FUNCTION notify_reservation_completed();

CREATE TRIGGER on_reservation_insert AFTER INSERT ON public.reservations FOR EACH ROW EXECUTE FUNCTION notify_reservation_insert();

CREATE TRIGGER trg_notify_staff_new_reservation AFTER INSERT ON public.reservations FOR EACH ROW EXECUTE FUNCTION notify_staff_new_reservation();

